def init_from_sorted(self, intervals):
    # assumes that intervals is a non-empty collection.
    # Else, next line raises IndexError
    center_iv = intervals[len(intervals) // 2]
    self.x_center = center_iv.begin
    self.s_center = set()
    s_left = []
    s_right = []
    for k in intervals:
        if k.end <= self.x_center:
            s_left.append(k)
        elif k.begin > self.x_center:
            s_right.append(k)
        else:
            self.s_center.add(k)
    self.left_node = self.__class__.from_sorted_intervals(s_left)
    self.right_node = self.__class__.from_sorted_intervals(s_right)
    return self.rotate()

